    "name": "spinner",
    "ext": "tsx",
    "source": "// Skeleton: shadcn/ui `bases/radix/ui/spinner.tsx` (MIT, see LICENSE-shadcn.md):\n// a spinning loader glyph, `size-4` unless the class says otherwise, no\n// variants. The glyph is lucide's Loader2 path (shadcn's default icon) drawn\n// with currentColor. Appearance: recipe (Spinner).\nimport * as React from 'react'\nimport { cn } from '@/lib/utils'\n\nfunction Spinner({ className, ...props }: React.ComponentProps<'svg'>) {\n  return (\n    <svg\n      data-slot=\"spinner\"\n      data-escala=\"Spinner\"\n      role=\"status\"\n      aria-label=\"Loading\"\n      viewBox=\"0 0 24 24\"\n      fill=\"none\"\n      stroke=\"currentColor\"\n      strokeWidth={2}\n      strokeLinecap=\"round\"\n      strokeLinejoin=\"round\"\n      className={cn('size-4 animate-spin motion-reduce:animate-none', className)}\n      {...props}\n    >\n      <path d=\"M21 12a9 9 0 1 1-6.219-8.56\" />\n    </svg>\n  )\n}\n\nexport { Spinner }\n",
